def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def main() -> None:
    inventory = []
    for rel in FILES:
        path = ROOT / rel
        if path.exists():
            inventory.append({"path": rel, "bytes": path.stat().st_size, "sha256": sha256(path)})
    try:
        revision = subprocess.run(["git", "rev-parse", "HEAD"], cwd=ROOT, capture_output=True,
                                  text=True, check=True).stdout.strip()
    except Exception:
        revision = None
    manifest = {
        "frozen_at": datetime.now(timezone.utc).isoformat(), "git_revision": revision,
        "python": platform.python_version(), "platform": platform.platform(),
        "protocol": {"name": "Hyperlane", "event": "Dispatch", "boundary": "Mailbox.nonce()"},
        "provenance_classes": {
            "live_natural_observation": "unmodified public RPC response collected live",
            "saved_natural_failure_live_replay": "saved unmodified failure at its real block plus live boundary/repair",
            "controlled_fault_injection": "explicitly mutated canonical trace",
            "controlled_integrity_mutation": "explicitly mutated message identity set",
        },
        "cost_model": {"eth_getLogs_cu": 60, "eth_call_cu": 26,
                       "note": "Published Alchemy CU reference; not universal provider billing."},
        "files": inventory,
    }
    out = ROOT / "data" / "experiment_manifest.json"
    out.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(out)


if __name__ == "__main__":
    main()
